-- import-3.3.0-reef.sql - met la base EmDash 0.38 de Reef a jour pour la 3.3.0 : cree la collection `sections` (les textes des pages, 26 entrees publiees par langue) si elle manque, puis corrige les textes que la 3.3.0 corrige dans les fichiers.
--
-- Parties 1 et 3 : la collection, relevee sur ce qu'EmDash 0.38 ecrit lui-meme (une base locale
-- vierge, la graine de la 3.1.3, puis celle de la collection par la meme porte, dev-bypass, et la
-- difference lue avec sqlite sur le fichier de la D1 locale). Seules les tables de cette
-- collection sont touchees : ni les billets, ni les options du site.
--
-- Partie 2 : les corrections de la 3.3.0 sur les lignes publiees ET sur leurs revisions, reperees
-- par slug et langue : l'hebergement des mentions legales (le site n'est plus un ensemble de
-- fichiers statiques), la confidentialite et les conditions reecrites pour un blog (ni compte, ni
-- abonnement, ni facturation), leur titre, leur chapo et leur date de revision. Une clause seule
-- se corrige par son fragment exact ; une liste reecrite, ou un champ, ne se remplace que s'il
-- porte encore le texte de la graine 3.1.4 : un texte deja corrige, ou reecrit depuis dans le
-- back office, n'est pas touche.
--
-- Idempotent : CREATE ... IF NOT EXISTS, INSERT OR IGNORE sur des cles fixes, UPDATE garde par
-- instr() ou par l'egalite avec l'ancien texte. Une deuxieme execution ne change rien.
--
-- Ordre : la table et ses index, les lignes (cles etrangeres d'abord), les corrections, puis les
-- declencheurs de l'index des medias, poses en dernier pour que l'import ne les declenche pas.
--
-- Execution (depuis le depot, compte Cloudflare connecte), une fois apres le deploiement :
--   npx wrangler d1 execute reef-moteur --remote --config wrangler.moteur.jsonc --file=seed/import-3.3.0-reef.sql
-- Suppose que la base n'a pas deja une collection `sections` creee autrement.

-- 1. La collection : table, index, lignes et revisions.
CREATE TABLE IF NOT EXISTS "ec_sections" ("id" text primary key, "slug" text, "status" text default 'draft', "author_id" text, "primary_byline_id" text, "created_at" text default (datetime('now')), "updated_at" text default (datetime('now')), "published_at" text, "scheduled_at" text, "deleted_at" text, "version" integer default 1, "live_revision_id" text references "revisions" ("id"), "draft_revision_id" text references "revisions" ("id"), "locale" text default 'en' not null, "translation_group" text, "title" text, "page" text default '' not null, "eyebrow" text, "accent" text, "lede" text, "arguments" json, "cta" text, "cta_secondary" text, "note" text, "meta_title" text, "meta_description" text, "revised" text, constraint "ec_sections_slug_locale_unique" unique ("slug", "locale"));
CREATE INDEX IF NOT EXISTS "idx_cf_01m39wn6f06xx5mg0gjq8wwkez"
			ON "ec_sections" (
				("page" IS NOT NULL),
				"page",
				id
			)
			WHERE deleted_at IS NULL
		;
CREATE INDEX IF NOT EXISTS "idx_cf_01m39wn6f06xx5mg0gjq8wwkez_loc"
			ON "ec_sections" (
				locale,
				("page" IS NOT NULL),
				"page",
				id
			)
			WHERE deleted_at IS NULL
		;
CREATE INDEX IF NOT EXISTS "idx_ec_sections_author"
			ON "ec_sections" (author_id)
		;
CREATE INDEX IF NOT EXISTS "idx_ec_sections_del_sched"
			ON "ec_sections" (deleted_at, scheduled_at)
			WHERE scheduled_at IS NOT NULL
		;
CREATE INDEX IF NOT EXISTS "idx_ec_sections_del_tg_locale"
			ON "ec_sections" (deleted_at, translation_group, locale)
		;
CREATE INDEX IF NOT EXISTS "idx_ec_sections_deleted_created_id"
			ON "ec_sections" (deleted_at, created_at DESC, id DESC)
		;
CREATE INDEX IF NOT EXISTS "idx_ec_sections_deleted_published_id"
			ON "ec_sections" (deleted_at, published_at DESC, id DESC)
		;
CREATE INDEX IF NOT EXISTS "idx_ec_sections_deleted_status"
			ON "ec_sections" (deleted_at, status)
		;
CREATE INDEX IF NOT EXISTS "idx_ec_sections_deleted_updated_id"
			ON "ec_sections" (deleted_at, updated_at DESC, id DESC)
		;
CREATE INDEX IF NOT EXISTS "idx_ec_sections_draft_revision"
			ON "ec_sections" (draft_revision_id)
		;
CREATE INDEX IF NOT EXISTS "idx_ec_sections_live_revision"
			ON "ec_sections" (live_revision_id)
		;
CREATE INDEX IF NOT EXISTS "idx_ec_sections_loc_crt"
			ON "ec_sections" (deleted_at, locale, created_at DESC, id DESC)
		;
CREATE INDEX IF NOT EXISTS "idx_ec_sections_loc_upd"
			ON "ec_sections" (deleted_at, locale, updated_at DESC, id DESC)
		;
CREATE INDEX IF NOT EXISTS "idx_ec_sections_locale"
			ON "ec_sections" (locale)
		;
CREATE INDEX IF NOT EXISTS "idx_ec_sections_primary_byline"
			ON "ec_sections" (primary_byline_id)
		;
CREATE INDEX IF NOT EXISTS "idx_ec_sections_slug"
			ON "ec_sections" (slug)
		;
CREATE INDEX IF NOT EXISTS "idx_ec_sections_tg_locale"
			ON "ec_sections" (translation_group, locale)
		;
