INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN6YWQD49S2JZJYRB653J', 'sections', '01M39WN6YN103KG8CCMDTM024D', '{"title":"Tout ce que nous avons écrit","page":"blog","eyebrow":"Archives","accent":"Tout","lede":"Les archives complètes, du plus récent au plus ancien. Trente secondes de défilement valent mieux qu''un champ de recherche quand on ne sait pas encore ce que l''on cherche.","meta_title":"Tous les articles","meta_description":"Tous les articles publiés sur Reef Notes, du plus récent au plus ancien : journaux de chantier, performance, typographie et gestion d''un petit studio."}', NULL, '2026-09-24 14:21:05');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN6ZH65Z7WZ7GGPG9ZRZ8', 'sections', '01M39WN6ZADCZMAYV8Q945NCTK', '{"title":"Five threads we keep pulling","page":"rubriques","eyebrow":"Topics","accent":"threads","lede":"Every post belongs to exactly one topic. Pick a thread and read it end to end, oldest first if you want the argument in order.","meta_title":"Topics","meta_description":"Every subject covered on Reef Notes: front-end craft, performance work, typography, and the business of running a small studio."}', NULL, '2026-09-24 14:21:05');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN705NSYB5SXJ5GCY692D', 'sections', '01M39WN6ZZC4PN8QHBQQ26WJB0', '{"title":"Cinq fils que nous tirons sans cesse","page":"rubriques","eyebrow":"Sujets","accent":"fils","lede":"Chaque article appartient à un seul sujet. Choisissez un fil et lisez-le d''un bout à l''autre, du plus ancien au plus récent si vous voulez l''argument dans l''ordre.","meta_title":"Sujets","meta_description":"Tous les sujets couverts par Reef Notes : artisanat du front-end, performance, typographie et gestion d''un petit studio."}', NULL, '2026-09-24 14:21:05');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN70RGCV1XKHVZTJB9YQJ', 'sections', '01M39WN70KMX46S6TNYD6T6DCH', '{"title":"Who writes here","page":"auteurs","eyebrow":"Authors","accent":"writes","lede":"Three people share this notebook. Every post carries a byline, and every byline leads to everything that person has written.","meta_title":"Authors","meta_description":"The people who write Reef Notes: what they work on day to day, where to find them elsewhere, and everything they have published here."}', NULL, '2026-09-24 14:21:05');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN71BQTKYGM9HBT7A9HG0', 'sections', '01M39WN715JG6HZ70MD47WT855', '{"title":"Qui écrit ici","page":"auteurs","eyebrow":"Auteurs","accent":"écrit","lede":"Trois personnes partagent ce carnet. Chaque article porte une signature, et chaque signature mène à tout ce que son auteur a écrit.","meta_title":"Auteurs","meta_description":"Les personnes qui écrivent Reef Notes : ce qu''elles font au quotidien, où les retrouver ailleurs, et tout ce qu''elles ont publié ici."}', NULL, '2026-09-24 14:21:05');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN721CDAJ3GCK8D14ES7A', 'sections', '01M39WN71RPR4E7GV7QKRDHG8F', '{"title":"Find it again","page":"recherche","eyebrow":"Search","accent":"again","lede":"Search covers titles, summaries, topics and tags. It runs in your browser, so nothing leaves the page and it keeps working offline once loaded.","meta_title":"Search","meta_description":"Search every post on Reef Notes by title, summary, topic or tag. It runs in your browser: nothing is sent to a server and nothing is logged."}', NULL, '2026-09-24 14:21:05');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN72N5TSDCY0MXJDGYMJ9', 'sections', '01M39WN72E7YQPRPA390TQYG8C', '{"title":"Retrouver un article","page":"recherche","eyebrow":"Recherche","accent":"Retrouver","lede":"La recherche couvre les titres, les résumés, les sujets et les étiquettes. Elle tourne dans votre navigateur : rien ne quitte la page, et elle fonctionne encore hors ligne une fois chargée.","meta_title":"Recherche","meta_description":"Cherchez dans tous les articles de Reef Notes par titre, résumé, sujet ou étiquette. La recherche tourne dans votre navigateur : rien n''est envoyé à un serveur, rien n''est enregistré."}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN736KB99VDRWNHRQEHQQ', 'sections', '01M39WN730HFR7MV3Q1EDKZYJS', '{"title":"A three-person studio that writes things down","page":"a-propos","eyebrow":"About","accent":"writes","lede":"We design and build websites for small teams. Reef Notes is where the working notes end up, because the useful part of a project is almost never the screenshot.","meta_title":"About the studio","meta_description":"Who runs Reef Notes, how the studio works, what we take on and what we turn down, and why the working notes are published instead of filed away."}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN73Y2VRV93DD3MJXNNQ8', 'sections', '01M39WN73N5A2A765YXJMAZ6TR', '{"title":"Un studio à trois qui note tout","page":"a-propos","eyebrow":"À propos","accent":"note","lede":"Nous dessinons et construisons des sites pour de petites équipes. Reef Notes est l''endroit où atterrissent les notes de travail, parce que la partie utile d''un projet n''est presque jamais la capture d''écran.","meta_title":"À propos du studio","meta_description":"Qui tient Reef Notes, comment le studio travaille, ce que nous acceptons et ce que nous refusons, et pourquoi les notes de chantier sont publiées plutôt que classées."}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN74SGP9S3FZSG0ECDTD7', 'sections', '01M39WN74GRS1570PVSCQDTFHM', '{"title":"How the notebook started","page":"a-propos","accent":"notebook","arguments":[{"body":"The studio opened in 2019 with one laptop and a spreadsheet of leads. The first year taught us that a website is rarely a design problem: it is a decision problem with a design attached. Which font loads first, which section gets cut, what happens on a four-year-old Android phone on hotel wifi."},{"body":"For three years the answers lived in a private repository. Every time a client asked why a page felt slow, or why we refused to add a fifth typeface, the reasoning was already written down somewhere. Publishing those notes cost us nothing and saved the same explanation twice a month."},{"body":"Reef Notes is that repository, cleaned up. Some entries are build logs with numbers in them, some are arguments about type, some cover the unglamorous half of freelancing: scoping, quoting, being paid on time. All of them come out of work we actually did."}]}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN75QMQ4SY18KGP8T0S3J', 'sections', '01M39WN75CVRV5ABT7EZFWQD2A', '{"title":"Comment le carnet a commencé","page":"a-propos","accent":"carnet","arguments":[{"body":"Le studio a ouvert en 2019 avec un portable et un tableur de prospects. La première année nous a appris qu''un site est rarement un problème de design : c''est un problème de décisions, avec un design posé par-dessus. Quelle police charge en premier, quelle section saute, ce qui se passe sur un Android de quatre ans connecté au wifi d''un hôtel."},{"body":"Pendant trois ans, les réponses sont restées dans un dépôt privé. Chaque fois qu''un client demandait pourquoi une page semblait lente, ou pourquoi nous refusions une cinquième police, le raisonnement était déjà écrit quelque part. Publier ces notes ne nous a rien coûté et nous a évité la même explication deux fois par mois."},{"body":"Reef Notes, c''est ce dépôt remis au propre. Certaines entrées sont des journaux de chantier avec des chiffres dedans, d''autres des prises de position sur la typographie, d''autres encore la moitié ingrate du métier : cadrer, chiffrer, être payé à l''heure. Toutes sortent de travaux réels."}]}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN76HXF4ZA04XEB4PY84Z', 'sections', '01M39WN7662K52SP018J1CCKDV', '{"title":"How we work","page":"a-propos","accent":"work","lede":"Three rules we have not yet found a good reason to break.","arguments":[{"title":"Measure before arguing","body":"Taste settles nothing about performance. We publish the before and after numbers, including the times a change made things worse."},{"title":"Ship the boring version","body":"The boring version launches on time, survives a redesign and still works with JavaScript off. Cleverness is what we add once the boring version is live."},{"title":"Write it down once","body":"If an answer takes more than five minutes to explain, it becomes a post. Clients get the link, we get our afternoon back."}]}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN7759D6ZHD4MTA1J5SSB', 'sections', '01M39WN76YRNHN8TV2ABTHYGW8', '{"title":"Notre façon de travailler","page":"a-propos","accent":"façon","lede":"Trois règles auxquelles nous n''avons pas encore trouvé de bonne raison de déroger.","arguments":[{"title":"Mesurer avant de discuter","body":"Le goût ne tranche rien en matière de performance. Nous publions les chiffres avant et après, y compris les fois où le changement a tout empiré."},{"title":"Livrer la version ennuyeuse","body":"La version ennuyeuse sort dans les temps, survit à une refonte et fonctionne encore sans JavaScript. L''astuce vient ensuite, une fois la version ennuyeuse en ligne."},{"title":"L''écrire une seule fois","body":"Si une réponse demande plus de cinq minutes d''explication, elle devient un article. Le client reçoit le lien, nous récupérons notre après-midi."}]}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN77P4T76ESH237KX3QTP', 'sections', '01M39WN77HK7JKX3N7AS759SFQ', '{"title":"The three of us","page":"a-propos","accent":"three","lede":"Short bios, honest job titles, and every post each of us has signed.","cta":"All authors"}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN788QHAC4M402PGX8QZR', 'sections', '01M39WN782E4VV8R99B76ZRDA2', '{"title":"Nous trois","page":"a-propos","accent":"trois","lede":"Trois biographies courtes, des intitulés honnêtes, et tous les articles que chacun a signés.","cta":"Tous les auteurs"}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN78RGC4VWKYKPGD5HYNS', 'sections', '01M39WN78K14WBM6R20FX292A8', '{"title":"Working together","page":"a-propos","lede":"We take on three or four projects a year, mostly redesigns for teams of under twenty people. If the timing lines up, tell us what is in the way.","cta":"Get in touch"}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN79C9PWA5Q7AGEWAREYS', 'sections', '01M39WN7974FQQ2KTYEKAMHAVM', '{"title":"Travailler ensemble","page":"a-propos","lede":"Nous prenons trois ou quatre projets par an, surtout des refontes pour des équipes de moins de vingt personnes. Si le calendrier s''y prête, dites-nous ce qui vous bloque.","cta":"Nous écrire"}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN79Z8XK5YE527590Z1DQ', 'sections', '01M39WN79R386V97SHNCQGJN16', '{"title":"Write to us, we read all of it","page":"contact","eyebrow":"Contact","accent":"all","lede":"A project, a correction, a question about a build: it lands in the same inbox and a person answers it. No ticket number, no autoresponder.","meta_title":"Contact","meta_description":"Project enquiries, a correction on a post, or a question about something we published. One inbox, read by a person, answered within two working days."}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN7AJBB7AVN04REJCE79P', 'sections', '01M39WN7AC3F97QFBJMJ8KG68T', '{"title":"Écrivez-nous, nous lisons tout","page":"contact","eyebrow":"Contact","accent":"tout","lede":"Un projet, une correction, une question sur un chantier : tout arrive dans la même boîte et une personne y répond. Pas de numéro de ticket, pas de réponse automatique.","meta_title":"Contact","meta_description":"Une demande de projet, une correction sur un article, une question sur ce que nous avons publié. Une seule boîte, lue par une personne, réponse sous deux jours ouvrés."}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN7B5Y83QFRAHMSG7594N', 'sections', '01M39WN7AY5G1YHY40HC5KBB22', '{"title":"Send a message","page":"contact","cta":"Send message","note":"No newsletter signup hidden in this form. Your address is used to reply, and for nothing else."}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN7BXHH6EBM4JE9D25RRB', 'sections', '01M39WN7BPN9FP3DGF6P3XF1AN', '{"title":"Envoyer un message","page":"contact","cta":"Envoyer le message","note":"Aucune inscription à la newsletter cachée dans ce formulaire. Votre adresse sert à vous répondre, et à rien d''autre."}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN7CKQ3YG5EQN1FESX9ZE', 'sections', '01M39WN7CB0YY35HHWJ2JDBT70', '{"title":"Or skip the form","page":"contact","lede":"Plain email works just as well, and a thread is easier to keep than a form.","cta":"Email the studio"}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN7DCHNAH01M0WGXXJYPY', 'sections', '01M39WN7D4AK62Z5VAG4VEFA13', '{"title":"Ou passez-vous du formulaire","page":"contact","lede":"Un simple email fait aussi bien l''affaire, et un fil de discussion se conserve mieux qu''un formulaire.","cta":"Écrire au studio"}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN7E234FVDV8NMS6EDPMF', 'sections', '01M39WN7DTAC3T92CFDQ9PQG6S', '{"title":"What happens next","page":"contact","arguments":[{"body":"A short reply within two working days, written by one of us."},{"body":"If it is a project, three questions come back before any number does."},{"body":"If it is a correction, the post is fixed and credited the same week."}]}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN7ETPJ20DWF27T2XK73G', 'sections', '01M39WN7EGDCF72CSZ1HF9BSYR', '{"title":"Ce qui se passe ensuite","page":"contact","arguments":[{"body":"Une réponse courte sous deux jours ouvrés, écrite par l''un de nous trois."},{"body":"S''il s''agit d''un projet, vous recevez trois questions avant le moindre chiffre."},{"body":"S''il s''agit d''une correction, l''article est repris et crédité dans la semaine."}]}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN7FE62YHTQ8SVFE30CWR', 'sections', '01M39WN7F8W9QYW38FW0XGWC8F', '{"title":"Legal notice","page":"mentions-legales","eyebrow":"Legal","lede":"Who publishes this site, who hosts it, and how to reach the publisher.","arguments":[{"title":"Publisher","body":"This site is published by [studio name], [legal form] registered at [full address], under number [registration number]. Publication director: [name]. Any question about the content published here can be sent through the contact page."},{"title":"Hosting","body":"The site is a set of static files served by [host name], [host address], reachable at [host contact]. There is no database, no server-side session and no account: nothing is stored on our side when you read a page."},{"title":"Content and reuse","body":"The posts, illustrations and code samples published here belong to their authors. Quoting a passage with a link back is welcome and needs no permission. Republishing a whole post, translated or not, does."},{"title":"Reporting a problem","body":"A factual error, a broken link, a copyright concern: write to the address on the contact page. Corrections are made within two working days and the post carries the date of its revision."}]}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN7G3ZXS64AV7RG2G9ENQ', 'sections', '01M39WN7FXCVYCHT4Q440BVBPJ', '{"title":"Mentions légales","page":"mentions-legales","eyebrow":"Légal","lede":"Qui publie ce site, qui l''héberge, et comment joindre l''éditeur.","arguments":[{"title":"Éditeur","body":"Ce site est édité par [nom du studio], [forme juridique] immatriculée à [adresse complète] sous le numéro [numéro d''immatriculation]. Directeur de la publication : [nom]. Toute question sur les contenus publiés ici peut nous être adressée depuis la page de contact."},{"title":"Hébergement","body":"Le site est un ensemble de fichiers statiques servis par [nom de l''hébergeur], [adresse de l''hébergeur], joignable au [contact de l''hébergeur]. Il n''y a ni base de données, ni session serveur, ni compte : rien n''est conservé de notre côté lorsque vous lisez une page."},{"title":"Contenus et réutilisation","body":"Les articles, les illustrations et les extraits de code publiés ici appartiennent à leurs auteurs. Citer un passage avec un lien de retour est bienvenu et ne demande aucune autorisation. Republier un article entier, traduit ou non, en demande une."},{"title":"Signaler un problème","body":"Une erreur factuelle, un lien mort, une question de droits : écrivez à l''adresse indiquée sur la page de contact. Les corrections sont faites sous deux jours ouvrés, et l''article porte alors la date de sa révision."}]}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN7GQWG8MRNARFGCVR8Y4', 'sections', '01M39WN7GHEJHEBGCRN8W3RYXY', '{"title":"Privacy policy","page":"confidentialite","lede":"What we collect, why we collect it, and the choices you have over your data.","arguments":[{"title":"Who we are","body":"This policy describes how we collect, use and protect personal information when you visit our website or use our service. It applies to visitors, trial users and paying customers alike. If you have any question about it, you can reach us at any time through the contact page."},{"title":"Information we collect","body":"We collect the information you give us directly, such as your name, email address and company details when you create an account or contact us. We also collect usage information generated as you use the service, such as pages visited, features used and device data, along with any content you choose to store in your workspace."},{"title":"How we use your information","body":"We use your information to provide and improve the service, to secure accounts, to respond to your requests, and to send service messages such as billing notices and important changes. With your consent, we may also send product news, and every such message includes a way to opt out."},{"title":"Legal bases for processing","body":"Where data protection law requires a legal basis, we rely on the performance of our contract with you, on our legitimate interest in operating and improving the service, on your consent where we ask for it, and on our legal obligations, for example in accounting matters."},{"title":"Cookies and analytics","body":"We use a small number of cookies to keep you signed in and to remember your preferences. Our analytics measure aggregate usage of the site and never build advertising profiles. You can block cookies in your browser; the parts of the site that do not require an account will keep working."},{"title":"How we share information","body":"We never sell personal information. We share it only with the processors that help us run the service, such as hosting, payment and email providers, each bound by a data processing agreement, and with authorities where the law requires it. A current list of processors is available on request."},{"title":"Data retention and deletion","body":"We keep personal information for as long as your account is active and for a limited period afterwards to comply with legal obligations. When you delete your account, or ask us to, we delete or anonymize your data within 30 days, except where a longer retention is required by law."},{"title":"Your rights","body":"Depending on where you live, you may have the right to access, correct, export, restrict or delete the personal information we hold about you, and to object to certain processing. To exercise any of these rights, contact us through the contact page and we will respond within the legal deadline."},{"title":"Changes to this policy","body":"We may update this policy as the service or the law evolves. When we make a material change, we will notify account holders by email or through the service before the change takes effect, and the date at the top of this page will always reflect the latest version."}],"revised":"2026-01-15T00:00:00.000Z"}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN7HB242N36MJFM4843VJ', 'sections', '01M39WN7H4EXT2KTSFAN0VVXHV', '{"title":"Politique de confidentialité","page":"confidentialite","lede":"Ce que nous collectons, pourquoi nous le collectons, et les choix qui vous reviennent.","arguments":[{"title":"Qui nous sommes","body":"Cette politique décrit la façon dont nous collectons, utilisons et protégeons les données personnelles lorsque vous consultez notre site ou utilisez le service. Elle vaut pour les visiteurs, les comptes d''essai et les clients payants, sans distinction. Toute question à son sujet peut nous être adressée à tout moment depuis la page de contact."},{"title":"Les données que nous collectons","body":"Nous collectons les données que vous nous confiez directement : nom, adresse email et informations sur votre entreprise lors de la création d''un compte ou d''une prise de contact. Nous collectons également les données d''usage produites au fil de votre utilisation du service, comme les pages consultées, les fonctions employées et les caractéristiques de votre appareil, ainsi que les contenus que vous choisissez de conserver dans votre espace de travail."},{"title":"L''usage que nous en faisons","body":"Vos données nous servent à fournir et à améliorer le service, à sécuriser les comptes, à répondre à vos demandes et à vous adresser les messages liés au service, tels que les avis de facturation et les changements importants. Avec votre accord, nous pouvons également vous envoyer des nouvelles du produit : chacun de ces messages comporte un moyen de s''y soustraire."},{"title":"Les bases légales du traitement","body":"Lorsque la réglementation sur la protection des données exige une base légale, nous nous appuyons sur l''exécution du contrat qui nous lie à vous, sur notre intérêt légitime à exploiter et à améliorer le service, sur votre consentement lorsque nous le sollicitons, et sur nos obligations légales, en matière comptable notamment."},{"title":"Cookies et mesure d''audience","body":"Nous utilisons un petit nombre de cookies, destinés à vous maintenir connecté et à mémoriser vos préférences. Notre mesure d''audience porte sur l''usage global du site et ne constitue jamais de profil publicitaire. Vous pouvez bloquer les cookies depuis votre navigateur : les parties du site qui ne demandent pas de compte continueront de fonctionner."},{"title":"Le partage de vos données","body":"Nous ne vendons jamais de données personnelles. Nous les partageons uniquement avec les sous-traitants qui nous aident à faire tourner le service, hébergement, paiement et envoi d''emails par exemple, chacun étant lié par un accord de traitement des données, ainsi qu''avec les autorités lorsque la loi l''impose. La liste à jour de ces sous-traitants est communiquée sur demande."},{"title":"Conservation et suppression","body":"Nous conservons les données personnelles tant que votre compte est actif, puis pendant une durée limitée afin de respecter nos obligations légales. Lorsque vous supprimez votre compte, ou que vous nous demandez de le faire, vos données sont supprimées ou anonymisées sous 30 jours, sauf lorsqu''une conservation plus longue nous est imposée par la loi."},{"title":"Vos droits","body":"Selon votre lieu de résidence, vous disposez du droit d''accéder aux données personnelles que nous détenons sur vous, de les rectifier, de les exporter, d''en limiter le traitement ou de les faire supprimer, ainsi que de vous opposer à certains traitements. Pour exercer l''un de ces droits, écrivez-nous depuis la page de contact : nous répondons dans le délai prévu par la loi."},{"title":"Modifications de cette politique","body":"Cette politique peut évoluer avec le service ou avec la réglementation. En cas de changement substantiel, les titulaires de compte en sont informés par email ou depuis le service avant son entrée en vigueur, et la date affichée en haut de cette page correspond toujours à la version en cours."}],"revised":"2026-01-15T00:00:00.000Z"}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN7HYEZ5DH2W495SFEFEV', 'sections', '01M39WN7HS6H2AJSY1EGABDQKP', '{"title":"Terms of service","page":"conditions","lede":"The agreement that governs your use of the service, in plain language.","arguments":[{"title":"Agreement to these terms","body":"By creating an account or using the service, you agree to these terms on your own behalf or on behalf of the organization you represent. If you do not agree with them, please do not use the service. If you accept for an organization, you confirm that you have authority to bind it."},{"title":"Your account","body":"You are responsible for your account credentials and for the activity that happens under your account. Keep your password secure, use accurate registration information, and tell us promptly if you suspect unauthorized access. Accounts are for organizations and their members, not for resale."},{"title":"Acceptable use","body":"You agree to use the service lawfully and respectfully. You will not attempt to breach its security, disrupt its operation, access data that is not yours, or use it to store or distribute unlawful, infringing or harmful content. We may suspend accounts that put the service or its users at risk."},{"title":"Your content and data","body":"You retain all rights to the content and data you bring into the service. You grant us the limited license needed to host, process and display that content in order to provide the service to you, and nothing more. You can export your data at any time in standard formats."},{"title":"Subscriptions and billing","body":"Paid plans are billed in advance, monthly or yearly, and renew automatically until cancelled. You can cancel at any time from the billing page, effective at the end of the current period. Prices may change with at least 30 days notice, and changes never apply retroactively to a period you have already paid."},{"title":"Termination","body":"You may stop using the service and delete your account at any time. We may suspend or terminate accounts that materially breach these terms, after notice where practical. After termination we make your data available for export for 30 days, then delete it in line with our privacy policy."},{"title":"Disclaimers and limitation of liability","body":"The service is provided as is, without warranties beyond those that cannot be excluded by law. To the maximum extent permitted, our total liability for any claim related to the service is limited to the amounts you paid us in the twelve months before the event giving rise to the claim."},{"title":"Changes to the service and these terms","body":"We improve the service continuously and may add, change or retire features. We may also update these terms; when a change is material, we will give account holders reasonable advance notice. Continued use of the service after a change takes effect constitutes acceptance of the new terms."},{"title":"Contact","body":"Questions about these terms, or about anything else in this document, are welcome through the contact page. For legal notices, use the postal or email address listed there, and we will confirm receipt as soon as possible."}],"revised":"2026-01-15T00:00:00.000Z"}', NULL, '2026-09-24 14:21:06');
INSERT OR IGNORE INTO "revisions" ("id", "collection", "entry_id", "data", "author_id", "created_at") VALUES ('01M39WN7JE9440T9VNASMQGMXP', 'sections', '01M39WN7J8XTZQYF52WQ3ZNJYQ', '{"title":"Conditions d''utilisation","page":"conditions","lede":"L''accord qui encadre votre utilisation du service, écrit en langage clair.","arguments":[{"title":"Acceptation des présentes conditions","body":"En créant un compte ou en utilisant le service, vous acceptez les présentes conditions, en votre nom propre ou au nom de l''organisation que vous représentez. Si vous ne les acceptez pas, n''utilisez pas le service. Si vous les acceptez pour une organisation, vous confirmez disposer du pouvoir de l''engager."},{"title":"Votre compte","body":"Vous répondez de vos identifiants et de tout ce qui se produit depuis votre compte. Gardez votre mot de passe en lieu sûr, renseignez des informations exactes à l''inscription et prévenez-nous sans tarder si vous soupçonnez un accès non autorisé. Les comptes sont destinés aux organisations et à leurs membres, jamais à la revente."},{"title":"Usage acceptable","body":"Vous vous engagez à utiliser le service dans le respect de la loi et d''autrui. Vous ne chercherez pas à contourner sa sécurité, à perturber son fonctionnement, à accéder à des données qui ne vous appartiennent pas, ni à vous en servir pour stocker ou diffuser des contenus illicites, contrefaisants ou nuisibles. Nous pouvons suspendre les comptes qui font courir un risque au service ou à ses utilisateurs."},{"title":"Vos contenus et vos données","body":"Vous conservez l''intégralité de vos droits sur les contenus et les données que vous apportez dans le service. Vous nous accordez la licence limitée nécessaire pour les héberger, les traiter et les afficher afin de vous fournir le service, et rien de plus. Vous pouvez exporter vos données à tout moment dans des formats standards."},{"title":"Abonnements et facturation","body":"Les offres payantes sont facturées d''avance, au mois ou à l''année, et se renouvellent automatiquement jusqu''à résiliation. Vous pouvez résilier à tout moment depuis la page de facturation, avec effet à la fin de la période en cours. Les tarifs peuvent évoluer moyennant un préavis d''au moins 30 jours, et aucune évolution ne s''applique rétroactivement à une période déjà réglée."},{"title":"Résiliation","body":"Vous pouvez cesser d''utiliser le service et supprimer votre compte quand vous le souhaitez. Nous pouvons suspendre ou fermer les comptes qui manquent gravement aux présentes conditions, après vous en avoir averti lorsque cela reste possible. Après la fermeture, vos données restent exportables pendant 30 jours, puis sont supprimées conformément à notre politique de confidentialité."},{"title":"Garanties et limitation de responsabilité","body":"Le service est fourni en l''état, sans autre garantie que celles que la loi ne permet pas d''écarter. Dans la limite autorisée par le droit applicable, notre responsabilité totale au titre de toute réclamation liée au service est plafonnée aux sommes que vous nous avez versées au cours des douze mois précédant le fait générateur."},{"title":"Évolutions du service et des conditions","body":"Nous améliorons le service en continu et pouvons ajouter, modifier ou retirer des fonctions. Les présentes conditions peuvent également être mises à jour : en cas de changement substantiel, les titulaires de compte en sont prévenus dans un délai raisonnable. Continuer d''utiliser le service après l''entrée en vigueur d''un changement vaut acceptation des nouvelles conditions."},{"title":"Nous contacter","body":"Toute question sur ces conditions, ou sur un autre point de ce document, est la bienvenue via la page de contact. Pour les notifications à caractère juridique, utilisez l''adresse postale ou électronique qui y figure : nous en accusons réception dans les meilleurs délais."}],"revised":"2026-01-15T00:00:00.000Z"}', NULL, '2026-09-24 14:21:06');
