INSERT OR IGNORE INTO "ec_sections" ("id", "slug", "status", "author_id", "primary_byline_id", "created_at", "updated_at", "published_at", "scheduled_at", "deleted_at", "version", "live_revision_id", "draft_revision_id", "locale", "translation_group", "title", "page", "eyebrow", "accent", "lede", "arguments", "cta", "cta_secondary", "note", "meta_title", "meta_description", "revised") VALUES ('01M39WN6JRTQV0A6KG6E4SHQFQ', 'hero', 'published', NULL, NULL, '2026-09-24T14:21:05.496Z', '2026-09-24T14:21:05.502Z', '2026-09-24T14:21:05.496Z', NULL, NULL, 2, '01M39WN6JZ2YAAB0WG6AW1GR49', NULL, 'fr', '01M39WN6HY8SEGHSY1M8TWQPXC', 'Notes d''un petit studio web', 'accueil', 'Reef Notes', 'petit', 'Ce qu''on apprend en construisant des sites, noté au fur et à mesure. Le carnet, pas le portfolio.', '[{"title":"notes publiées"},{"title":"fils"},{"title":"langues"}]', 'Commencer à lire', 'À propos du studio', NULL, 'Reef Notes, le carnet de bord d''un studio web indépendant', 'Journaux de chantier, temps de chargement, typographie et gestion d''un petit studio web. En français et en anglais, quelques notes par mois, écrites par les trois personnes qui font le travail.', NULL);
