INSERT OR IGNORE INTO "ec_sections" ("id", "slug", "status", "author_id", "primary_byline_id", "created_at", "updated_at", "published_at", "scheduled_at", "deleted_at", "version", "live_revision_id", "draft_revision_id", "locale", "translation_group", "title", "page", "eyebrow", "accent", "lede", "arguments", "cta", "cta_secondary", "note", "meta_title", "meta_description", "revised") VALUES ('01M39WN6N27JMXKFBDDWERK771', 'studio', 'published', NULL, NULL, '2026-09-24T14:21:05.570Z', '2026-09-24T14:21:05.575Z', '2026-09-24T14:21:05.570Z', NULL, NULL, 2, '01M39WN6N93AZN02Z2F94CZ16S', NULL, 'fr', '01M39WN6MG5M064P77ZSSDRP4E', 'Le studio derrière les notes', 'accueil', NULL, 'studio', 'L''un construit, l''une mesure, l''autre dessine, et tous les trois écrivent. Trois ou quatre projets par an, et tout ce qu''ils nous apprennent finit ici.', NULL, 'Notre façon de travailler', NULL, NULL, NULL, NULL, NULL);
