UPDATE "ec_sections" SET "arguments" = replace("arguments", '"body":"The site is a set of static files served by [host name], [host address], reachable at [host contact]. There is no database, no server-side session and no account: nothing is stored on our side when you read a page."', '"body":"The site is served by [host name], [host address], reachable at [host contact]. Reading a page creates no account and no session: nothing about you is stored on our side."') WHERE slug = 'mentions-legales' AND locale = 'en' AND instr("arguments", '"body":"The site is a set of static files served by [host name], [host address], reachable at [host contact]. There is no database, no server-side session and no account: nothing is stored on our side when you read a page."') > 0;
UPDATE "revisions" SET "data" = replace("data", '"body":"The site is a set of static files served by [host name], [host address], reachable at [host contact]. There is no database, no server-side session and no account: nothing is stored on our side when you read a page."', '"body":"The site is served by [host name], [host address], reachable at [host contact]. Reading a page creates no account and no session: nothing about you is stored on our side."') WHERE "collection" = 'sections' AND "entry_id" IN (SELECT "id" FROM "ec_sections" WHERE slug = 'mentions-legales' AND locale = 'en') AND instr("data", '"body":"The site is a set of static files served by [host name], [host address], reachable at [host contact]. There is no database, no server-side session and no account: nothing is stored on our side when you read a page."') > 0;
UPDATE "ec_sections" SET "arguments" = replace("arguments", '"body":"Le site est un ensemble de fichiers statiques servis par [nom de l''hébergeur], [adresse de l''hébergeur], joignable au [contact de l''hébergeur]. Il n''y a ni base de données, ni session serveur, ni compte : rien n''est conservé de notre côté lorsque vous lisez une page."', '"body":"Le site est servi par [nom de l''hébergeur], [adresse de l''hébergeur], joignable au [contact de l''hébergeur]. Lire une page ne crée ni compte ni session : rien ne vous concernant n''est conservé de notre côté."') WHERE slug = 'mentions-legales' AND locale = 'fr' AND instr("arguments", '"body":"Le site est un ensemble de fichiers statiques servis par [nom de l''hébergeur], [adresse de l''hébergeur], joignable au [contact de l''hébergeur]. Il n''y a ni base de données, ni session serveur, ni compte : rien n''est conservé de notre côté lorsque vous lisez une page."') > 0;
UPDATE "revisions" SET "data" = replace("data", '"body":"Le site est un ensemble de fichiers statiques servis par [nom de l''hébergeur], [adresse de l''hébergeur], joignable au [contact de l''hébergeur]. Il n''y a ni base de données, ni session serveur, ni compte : rien n''est conservé de notre côté lorsque vous lisez une page."', '"body":"Le site est servi par [nom de l''hébergeur], [adresse de l''hébergeur], joignable au [contact de l''hébergeur]. Lire une page ne crée ni compte ni session : rien ne vous concernant n''est conservé de notre côté."') WHERE "collection" = 'sections' AND "entry_id" IN (SELECT "id" FROM "ec_sections" WHERE slug = 'mentions-legales' AND locale = 'fr') AND instr("data", '"body":"Le site est un ensemble de fichiers statiques servis par [nom de l''hébergeur], [adresse de l''hébergeur], joignable au [contact de l''hébergeur]. Il n''y a ni base de données, ni session serveur, ni compte : rien n''est conservé de notre côté lorsque vous lisez une page."') > 0;
