UPDATE "ec_sections" SET "arguments" = '[{"title":"Who we are","body":"This policy describes what this site collects when you read it, subscribe to its newsletter or write to us. If you have any question about it, you can reach us at any time through the contact page."},{"title":"Information we collect","body":"Reading a page collects nothing about you. If you subscribe to the newsletter, we keep your email address; if you write to us, we keep your message and your address to answer it."},{"title":"How we use your information","body":"Your email address is used to send you the newsletter you asked for, and nothing else; every issue includes a way to unsubscribe. Your message is used to answer you."},{"title":"Legal bases for processing","body":"Where data protection law requires a legal basis, we rely on your consent for the newsletter, on our legitimate interest in answering the messages you send us, and on our legal obligations."},{"title":"Cookies and analytics","body":"This site sets no advertising cookie and runs no analytics. Your browser keeps your light or dark theme preference and, if you switch language, a cookie that remembers that choice."},{"title":"How we share information","body":"We never sell personal information. We share it only with the processors that help us run the site, such as the host and the email provider that sends the newsletter, each bound by a data processing agreement, and with authorities where the law requires it."},{"title":"Data retention and deletion","body":"A newsletter address is deleted when you unsubscribe; a message is deleted once the conversation is over."},{"title":"Your rights","body":"Depending on where you live, you may have the right to access, correct, export, restrict or delete the personal information we hold about you, and to object to certain processing. To exercise any of these rights, contact us through the contact page and we will respond within the legal deadline."},{"title":"Changes to this policy","body":"We may update this policy as the site or the law evolves. The date at the top of this page always gives the latest version."}]' WHERE slug = 'confidentialite' AND locale = 'en' AND "arguments" = '[{"title":"Who we are","body":"This policy describes how we collect, use and protect personal information when you visit our website or use our service. It applies to visitors, trial users and paying customers alike. If you have any question about it, you can reach us at any time through the contact page."},{"title":"Information we collect","body":"We collect the information you give us directly, such as your name, email address and company details when you create an account or contact us. We also collect usage information generated as you use the service, such as pages visited, features used and device data, along with any content you choose to store in your workspace."},{"title":"How we use your information","body":"We use your information to provide and improve the service, to secure accounts, to respond to your requests, and to send service messages such as billing notices and important changes. With your consent, we may also send product news, and every such message includes a way to opt out."},{"title":"Legal bases for processing","body":"Where data protection law requires a legal basis, we rely on the performance of our contract with you, on our legitimate interest in operating and improving the service, on your consent where we ask for it, and on our legal obligations, for example in accounting matters."},{"title":"Cookies and analytics","body":"We use a small number of cookies to keep you signed in and to remember your preferences. Our analytics measure aggregate usage of the site and never build advertising profiles. You can block cookies in your browser; the parts of the site that do not require an account will keep working."},{"title":"How we share information","body":"We never sell personal information. We share it only with the processors that help us run the service, such as hosting, payment and email providers, each bound by a data processing agreement, and with authorities where the law requires it. A current list of processors is available on request."},{"title":"Data retention and deletion","body":"We keep personal information for as long as your account is active and for a limited period afterwards to comply with legal obligations. When you delete your account, or ask us to, we delete or anonymize your data within 30 days, except where a longer retention is required by law."},{"title":"Your rights","body":"Depending on where you live, you may have the right to access, correct, export, restrict or delete the personal information we hold about you, and to object to certain processing. To exercise any of these rights, contact us through the contact page and we will respond within the legal deadline."},{"title":"Changes to this policy","body":"We may update this policy as the service or the law evolves. When we make a material change, we will notify account holders by email or through the service before the change takes effect, and the date at the top of this page will always reflect the latest version."}]';
UPDATE "revisions" SET "data" = replace("data", '"arguments":[{"title":"Who we are","body":"This policy describes how we collect, use and protect personal information when you visit our website or use our service. It applies to visitors, trial users and paying customers alike. If you have any question about it, you can reach us at any time through the contact page."},{"title":"Information we collect","body":"We collect the information you give us directly, such as your name, email address and company details when you create an account or contact us. We also collect usage information generated as you use the service, such as pages visited, features used and device data, along with any content you choose to store in your workspace."},{"title":"How we use your information","body":"We use your information to provide and improve the service, to secure accounts, to respond to your requests, and to send service messages such as billing notices and important changes. With your consent, we may also send product news, and every such message includes a way to opt out."},{"title":"Legal bases for processing","body":"Where data protection law requires a legal basis, we rely on the performance of our contract with you, on our legitimate interest in operating and improving the service, on your consent where we ask for it, and on our legal obligations, for example in accounting matters."},{"title":"Cookies and analytics","body":"We use a small number of cookies to keep you signed in and to remember your preferences. Our analytics measure aggregate usage of the site and never build advertising profiles. You can block cookies in your browser; the parts of the site that do not require an account will keep working."},{"title":"How we share information","body":"We never sell personal information. We share it only with the processors that help us run the service, such as hosting, payment and email providers, each bound by a data processing agreement, and with authorities where the law requires it. A current list of processors is available on request."},{"title":"Data retention and deletion","body":"We keep personal information for as long as your account is active and for a limited period afterwards to comply with legal obligations. When you delete your account, or ask us to, we delete or anonymize your data within 30 days, except where a longer retention is required by law."},{"title":"Your rights","body":"Depending on where you live, you may have the right to access, correct, export, restrict or delete the personal information we hold about you, and to object to certain processing. To exercise any of these rights, contact us through the contact page and we will respond within the legal deadline."},{"title":"Changes to this policy","body":"We may update this policy as the service or the law evolves. When we make a material change, we will notify account holders by email or through the service before the change takes effect, and the date at the top of this page will always reflect the latest version."}]', '"arguments":[{"title":"Who we are","body":"This policy describes what this site collects when you read it, subscribe to its newsletter or write to us. If you have any question about it, you can reach us at any time through the contact page."},{"title":"Information we collect","body":"Reading a page collects nothing about you. If you subscribe to the newsletter, we keep your email address; if you write to us, we keep your message and your address to answer it."},{"title":"How we use your information","body":"Your email address is used to send you the newsletter you asked for, and nothing else; every issue includes a way to unsubscribe. Your message is used to answer you."},{"title":"Legal bases for processing","body":"Where data protection law requires a legal basis, we rely on your consent for the newsletter, on our legitimate interest in answering the messages you send us, and on our legal obligations."},{"title":"Cookies and analytics","body":"This site sets no advertising cookie and runs no analytics. Your browser keeps your light or dark theme preference and, if you switch language, a cookie that remembers that choice."},{"title":"How we share information","body":"We never sell personal information. We share it only with the processors that help us run the site, such as the host and the email provider that sends the newsletter, each bound by a data processing agreement, and with authorities where the law requires it."},{"title":"Data retention and deletion","body":"A newsletter address is deleted when you unsubscribe; a message is deleted once the conversation is over."},{"title":"Your rights","body":"Depending on where you live, you may have the right to access, correct, export, restrict or delete the personal information we hold about you, and to object to certain processing. To exercise any of these rights, contact us through the contact page and we will respond within the legal deadline."},{"title":"Changes to this policy","body":"We may update this policy as the site or the law evolves. The date at the top of this page always gives the latest version."}]') WHERE "collection" = 'sections' AND "entry_id" IN (SELECT "id" FROM "ec_sections" WHERE slug = 'confidentialite' AND locale = 'en') AND instr("data", '"arguments":[{"title":"Who we are","body":"This policy describes how we collect, use and protect personal information when you visit our website or use our service. It applies to visitors, trial users and paying customers alike. If you have any question about it, you can reach us at any time through the contact page."},{"title":"Information we collect","body":"We collect the information you give us directly, such as your name, email address and company details when you create an account or contact us. We also collect usage information generated as you use the service, such as pages visited, features used and device data, along with any content you choose to store in your workspace."},{"title":"How we use your information","body":"We use your information to provide and improve the service, to secure accounts, to respond to your requests, and to send service messages such as billing notices and important changes. With your consent, we may also send product news, and every such message includes a way to opt out."},{"title":"Legal bases for processing","body":"Where data protection law requires a legal basis, we rely on the performance of our contract with you, on our legitimate interest in operating and improving the service, on your consent where we ask for it, and on our legal obligations, for example in accounting matters."},{"title":"Cookies and analytics","body":"We use a small number of cookies to keep you signed in and to remember your preferences. Our analytics measure aggregate usage of the site and never build advertising profiles. You can block cookies in your browser; the parts of the site that do not require an account will keep working."},{"title":"How we share information","body":"We never sell personal information. We share it only with the processors that help us run the service, such as hosting, payment and email providers, each bound by a data processing agreement, and with authorities where the law requires it. A current list of processors is available on request."},{"title":"Data retention and deletion","body":"We keep personal information for as long as your account is active and for a limited period afterwards to comply with legal obligations. When you delete your account, or ask us to, we delete or anonymize your data within 30 days, except where a longer retention is required by law."},{"title":"Your rights","body":"Depending on where you live, you may have the right to access, correct, export, restrict or delete the personal information we hold about you, and to object to certain processing. To exercise any of these rights, contact us through the contact page and we will respond within the legal deadline."},{"title":"Changes to this policy","body":"We may update this policy as the service or the law evolves. When we make a material change, we will notify account holders by email or through the service before the change takes effect, and the date at the top of this page will always reflect the latest version."}]') > 0;
