UPDATE "ec_sections" SET "arguments" = '[{"title":"Qui nous sommes","body":"Cette politique décrit ce que ce site recueille lorsque vous le lisez, vous abonnez à son infolettre ou nous écrivez. Toute question à son sujet peut nous être adressée à tout moment depuis la page de contact."},{"title":"Les données que nous collectons","body":"Lire une page ne recueille rien sur vous. Si vous vous abonnez à l''infolettre, nous conservons votre adresse e-mail ; si vous nous écrivez, nous conservons votre message et votre adresse pour vous répondre."},{"title":"L''usage que nous en faisons","body":"Votre adresse e-mail sert à vous envoyer l''infolettre que vous avez demandée, et à rien d''autre ; chaque envoi comporte un moyen de vous désabonner. Votre message sert à vous répondre."},{"title":"Les bases légales du traitement","body":"Lorsque la réglementation sur la protection des données exige une base légale, nous nous appuyons sur votre consentement pour l''infolettre, sur notre intérêt légitime à répondre aux messages que vous nous adressez, et sur nos obligations légales."},{"title":"Cookies et mesure d''audience","body":"Ce site ne dépose aucun cookie publicitaire et ne mesure pas l''audience. Votre navigateur conserve votre préférence de thème clair ou sombre et, si vous changez de langue, un cookie qui retient ce choix."},{"title":"Le partage de vos données","body":"Nous ne vendons jamais de données personnelles. Nous les partageons uniquement avec les sous-traitants qui nous aident à faire tourner le site, l''hébergeur et le service d''envoi de l''infolettre par exemple, chacun étant lié par un accord de traitement des données, ainsi qu''avec les autorités lorsque la loi l''impose."},{"title":"Conservation et suppression","body":"Une adresse d''infolettre est supprimée à la désinscription ; un message l''est une fois l''échange terminé."},{"title":"Vos droits","body":"Selon votre lieu de résidence, vous disposez du droit d''accéder aux données personnelles que nous détenons sur vous, de les rectifier, de les exporter, d''en limiter le traitement ou de les faire supprimer, ainsi que de vous opposer à certains traitements. Pour exercer l''un de ces droits, écrivez-nous depuis la page de contact : nous répondons dans le délai prévu par la loi."},{"title":"Modifications de cette politique","body":"Cette politique peut évoluer avec le site ou avec la réglementation. La date en haut de cette page donne toujours la dernière version."}]' WHERE slug = 'confidentialite' AND locale = 'fr' AND "arguments" = '[{"title":"Qui nous sommes","body":"Cette politique décrit la façon dont nous collectons, utilisons et protégeons les données personnelles lorsque vous consultez notre site ou utilisez le service. Elle vaut pour les visiteurs, les comptes d''essai et les clients payants, sans distinction. Toute question à son sujet peut nous être adressée à tout moment depuis la page de contact."},{"title":"Les données que nous collectons","body":"Nous collectons les données que vous nous confiez directement : nom, adresse email et informations sur votre entreprise lors de la création d''un compte ou d''une prise de contact. Nous collectons également les données d''usage produites au fil de votre utilisation du service, comme les pages consultées, les fonctions employées et les caractéristiques de votre appareil, ainsi que les contenus que vous choisissez de conserver dans votre espace de travail."},{"title":"L''usage que nous en faisons","body":"Vos données nous servent à fournir et à améliorer le service, à sécuriser les comptes, à répondre à vos demandes et à vous adresser les messages liés au service, tels que les avis de facturation et les changements importants. Avec votre accord, nous pouvons également vous envoyer des nouvelles du produit : chacun de ces messages comporte un moyen de s''y soustraire."},{"title":"Les bases légales du traitement","body":"Lorsque la réglementation sur la protection des données exige une base légale, nous nous appuyons sur l''exécution du contrat qui nous lie à vous, sur notre intérêt légitime à exploiter et à améliorer le service, sur votre consentement lorsque nous le sollicitons, et sur nos obligations légales, en matière comptable notamment."},{"title":"Cookies et mesure d''audience","body":"Nous utilisons un petit nombre de cookies, destinés à vous maintenir connecté et à mémoriser vos préférences. Notre mesure d''audience porte sur l''usage global du site et ne constitue jamais de profil publicitaire. Vous pouvez bloquer les cookies depuis votre navigateur : les parties du site qui ne demandent pas de compte continueront de fonctionner."},{"title":"Le partage de vos données","body":"Nous ne vendons jamais de données personnelles. Nous les partageons uniquement avec les sous-traitants qui nous aident à faire tourner le service, hébergement, paiement et envoi d''emails par exemple, chacun étant lié par un accord de traitement des données, ainsi qu''avec les autorités lorsque la loi l''impose. La liste à jour de ces sous-traitants est communiquée sur demande."},{"title":"Conservation et suppression","body":"Nous conservons les données personnelles tant que votre compte est actif, puis pendant une durée limitée afin de respecter nos obligations légales. Lorsque vous supprimez votre compte, ou que vous nous demandez de le faire, vos données sont supprimées ou anonymisées sous 30 jours, sauf lorsqu''une conservation plus longue nous est imposée par la loi."},{"title":"Vos droits","body":"Selon votre lieu de résidence, vous disposez du droit d''accéder aux données personnelles que nous détenons sur vous, de les rectifier, de les exporter, d''en limiter le traitement ou de les faire supprimer, ainsi que de vous opposer à certains traitements. Pour exercer l''un de ces droits, écrivez-nous depuis la page de contact : nous répondons dans le délai prévu par la loi."},{"title":"Modifications de cette politique","body":"Cette politique peut évoluer avec le service ou avec la réglementation. En cas de changement substantiel, les titulaires de compte en sont informés par email ou depuis le service avant son entrée en vigueur, et la date affichée en haut de cette page correspond toujours à la version en cours."}]';
