UPDATE "ec_sections" SET "arguments" = '[{"title":"Agreement to these terms","body":"By reading this site you accept these terms. If you do not accept them, please do not use it."},{"title":"Acceptable use","body":"You agree to use the site lawfully and respectfully. You will not attempt to breach its security, disrupt its operation, access data that is not yours, or use its forms to send unlawful or harmful content."},{"title":"Disclaimers and limitation of liability","body":"The site and its posts are provided as is, without warranties beyond those that cannot be excluded by law. A post reflects what its author knew on the date it carries; check anything you rely on. To the maximum extent permitted, we are not liable for decisions you make on the basis of what you read here."},{"title":"Changes to the site and these terms","body":"Posts are added, corrected and sometimes retired. These terms may also be updated; the date at the top of this page always gives the latest version."},{"title":"Contact","body":"Questions about these terms, or about anything else in this document, are welcome through the contact page. For legal notices, use the postal or email address listed there, and we will confirm receipt as soon as possible."}]' WHERE slug = 'conditions' AND locale = 'en' AND "arguments" = '[{"title":"Agreement to these terms","body":"By creating an account or using the service, you agree to these terms on your own behalf or on behalf of the organization you represent. If you do not agree with them, please do not use the service. If you accept for an organization, you confirm that you have authority to bind it."},{"title":"Your account","body":"You are responsible for your account credentials and for the activity that happens under your account. Keep your password secure, use accurate registration information, and tell us promptly if you suspect unauthorized access. Accounts are for organizations and their members, not for resale."},{"title":"Acceptable use","body":"You agree to use the service lawfully and respectfully. You will not attempt to breach its security, disrupt its operation, access data that is not yours, or use it to store or distribute unlawful, infringing or harmful content. We may suspend accounts that put the service or its users at risk."},{"title":"Your content and data","body":"You retain all rights to the content and data you bring into the service. You grant us the limited license needed to host, process and display that content in order to provide the service to you, and nothing more. You can export your data at any time in standard formats."},{"title":"Subscriptions and billing","body":"Paid plans are billed in advance, monthly or yearly, and renew automatically until cancelled. You can cancel at any time from the billing page, effective at the end of the current period. Prices may change with at least 30 days notice, and changes never apply retroactively to a period you have already paid."},{"title":"Termination","body":"You may stop using the service and delete your account at any time. We may suspend or terminate accounts that materially breach these terms, after notice where practical. After termination we make your data available for export for 30 days, then delete it in line with our privacy policy."},{"title":"Disclaimers and limitation of liability","body":"The service is provided as is, without warranties beyond those that cannot be excluded by law. To the maximum extent permitted, our total liability for any claim related to the service is limited to the amounts you paid us in the twelve months before the event giving rise to the claim."},{"title":"Changes to the service and these terms","body":"We improve the service continuously and may add, change or retire features. We may also update these terms; when a change is material, we will give account holders reasonable advance notice. Continued use of the service after a change takes effect constitutes acceptance of the new terms."},{"title":"Contact","body":"Questions about these terms, or about anything else in this document, are welcome through the contact page. For legal notices, use the postal or email address listed there, and we will confirm receipt as soon as possible."}]';
